<template>
  <LayoutHeader><template #left-header><ViewBreadcrumbs routeName="Lead Sales Reports" /></template><template #right-header><Button :label="__('Làm mới')" iconLeft="refresh-cw" :loading="resource.loading" @click="reload" /></template></LayoutHeader>
  <main class="h-full overflow-y-auto bg-surface-gray-2/40 p-4 sm:p-5"><div class="mx-auto max-w-7xl"><LeadSalesPageState :loading="resource.loading" :error="resource.error" :has-data="Boolean(data)" @retry="reload"><section class="mb-4 flex flex-wrap items-end justify-between gap-3"><div><h1 class="text-xl font-semibold">{{ __('Báo cáo nhóm') }}</h1><LeadSalesDefinition class="mt-1" :definition="workspaceDefinition(data)" :timestamp="formatWorkspaceTimestamp(data)" /></div><FormControl v-model="period" type="select" :options="periods" :label="__('Kỳ báo cáo')" class="w-44" @update:modelValue="reload" /></section><LeadSalesKpiGrid v-if="cards.length" :kpis="cards" /><p v-else class="rounded-lg border border-outline-gray-2 bg-surface-white p-6 text-sm text-ink-gray-5">{{ __('Chưa có chỉ số báo cáo cho kỳ đã chọn.') }}</p></LeadSalesPageState></div></main>
</template>
<script setup>
import LayoutHeader from '@/components/LayoutHeader.vue'; import ViewBreadcrumbs from '@/components/ViewBreadcrumbs.vue'; import LeadSalesDefinition from '@/components/LeadSales/LeadSalesDefinition.vue'; import LeadSalesKpiGrid from '@/components/LeadSales/LeadSalesKpiGrid.vue'; import LeadSalesPageState from '@/components/LeadSales/LeadSalesPageState.vue'; import { createLeadSalesWorkspaceResource, formatWorkspaceTimestamp, workspaceDefinition, workspaceRows } from '@/data/leadSalesWorkspace'; import { Button, FormControl } from 'frappe-ui'; import { computed, ref } from 'vue'
const period = ref('30d'); const resource = createLeadSalesWorkspaceResource('reports', { period: period.value }); const data = computed(() => resource.data); const cards = computed(() => workspaceRows(data.value, 'cards')); const periods = [{ label: __('7 ngày'), value: '7d' }, { label: __('30 ngày'), value: '30d' }, { label: __('Tháng này'), value: 'this_month' }]; function reload() { resource.submit({ period: period.value }) }
</script>
